const stats = $input.first().json;
const target = 500;
const confirmed = parseInt(stats.total_registrations || 0, 10);
const remaining = Math.max(target - confirmed, 0);
const pacePercent = Math.round((confirmed / target) * 100);

return [{
  json: {
    confirmed,
    target,
    remaining,
    pacePercent,
    referrals: parseInt(stats.referral_registrations || 0, 10),
    referrers: parseInt(stats.active_referrers || 0, 10),
    message: `📊 NxtWave GrowthOS Daily Briefing:\n- Confirmed: ${confirmed}/${target} (${pacePercent}%)\n- Remaining: ${remaining}\n- Referral Signups: ${stats.referral_registrations || 0}`
  }
}];
